function toSignificantFigures(v, n){
  v=Number(v); if(!isFinite(v)) return {ok:false, reason:'not a finite number'};
  n=Number(n); if(!(n>=1) || n>15) return {ok:false, reason:'digits must be 1-15'};
  if(v===0) return {ok:true, value:'0'};
  var p=v.toPrecision(n);
  var em=/^([+-]?)(\d)(?:\.(\d*))?[eE]([+-]?\d+)$/.exec(p);
  if(em){
    var sign=em[1]==='-'?'-':'', digits=em[2]+(em[3]||''), exp=parseInt(em[4],10), plain;
    if(exp>=0){
      if(digits.length>exp+1) plain=digits.slice(0,exp+1)+'.'+digits.slice(exp+1);
      else { plain=digits; for(var k=digits.length;k<=exp;k++) plain+='0'; }
    } else {
      plain='0.'; for(var j=-1;j>exp;j--) plain+='0'; plain+=digits;
    }
    p=sign+plain;
  }
  if(p.indexOf('.')>=0) p=p.replace(/0+$/,'').replace(/\.$/,'');
  return {ok:true, value:p};
}

var EXPORTS={toSignificantFigures:toSignificantFigures};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SigFigForgePure = EXPORTS; }
